def articles_for(is_super=False, yclients=True):
    result=[]
    for article in ARTICLES:
        if article.get('super_only') and not is_super:continue
        if article.get('branch_only') and is_super:continue
        if article.get('yclients') and not yclients:continue
        if article.get('standalone') and yclients and not is_super:continue
        result.append(dict(article))
    available={item['id'] for item in result}
    for item in result:item['related']=[key for key in item.get('related',[]) if key in available]
    return result
